import{_ as a,o as t,c as o,a2 as n}from"./chunks/framework.D66Xq0Kv.js";const p=JSON.parse('{"title":"Proving guards, not guessing them","description":"Guard validation used to be textual, a call with the right name near the sink. The value lattice changed that - and has limits we state here.","frontmatter":{"written-against-version":"0.7.1-preview.1","fact-checked":"2026-10-24","source-revision":"8a0ef9d-dirty","title":"Proving guards, not guessing them","date":"2026-09-21T00:00:00.000Z","description":"Guard validation used to be textual, a call with the right name near the sink. The value lattice changed that - and has limits we state here."},"headers":[],"relativePath":"blog/2026-09-21-value-aware-guards.md","filePath":"blog/2026-09-21-value-aware-guards.md"}'),r={name:"blog/2026-09-21-value-aware-guards.md"};function s(i,e,c,d,l,h){return t(),o("div",null,[...e[0]||(e[0]=[n('<blockquote><p><strong>Provenance.</strong> Behavioral claims in this post were written against Frensense 0.7.x and fact-checked on source rev <code>d6cfd3f</code> (0.8.0-beta). Mechanism references: <code>frensense-engine/src/analysis/value.rs</code>, <code>checks/policy.rs</code>, <code>checks/oob.rs</code>. The live per-CWE benchmark table in <code>docs/BENCHMARKING.md</code> is the source of truth for any accuracy number.</p></blockquote><h1 id="proving-guards-not-guessing-them" tabindex="-1">Proving guards, not guessing them <a class="header-anchor" href="#proving-guards-not-guessing-them" aria-label="Permalink to &quot;Proving guards, not guessing them&quot;">​</a></h1><p>Early versions of the engine accepted a guard if a plausible-sounding check appeared on the path to a sink. That works until it doesn&#39;t: <code>if (i &lt; 10)</code> guards <code>arr[i]</code>, but only because <code>10</code> happens to relate to the array, knowledge the text of the call does not carry.</p><p>The value lattice fixes the reasoning, not the pattern:</p><ul><li><strong>Constants and ranges</strong> flow through the analysis.</li><li><strong>Branch sharpening</strong> narrows values inside each <code>if</code>/<code>match</code> arm by the constraints the predicate implies.</li><li><strong>The GuardMap</strong> records which guard dominates which block, and <code>if i &lt; arr.len()</code> <em>provably</em> dominates <code>arr[i]</code> inside the arm.</li></ul><p>The same machinery powers the learned policy checks: a corpus bundle can require that a call only happen behind a range check, and the engine accepts a guard only when the lattice proves the bound, false positives on clean code drop accordingly.</p><p>This is the foundation the out-of-bounds checker is built on, and the relational (octagon) domain is the next step: tracking <em>relationships</em> between variables, not just their individual ranges.</p><h2 id="limits-of-the-proof-stated-plainly" tabindex="-1">Limits of the proof, stated plainly <a class="header-anchor" href="#limits-of-the-proof-stated-plainly" aria-label="Permalink to &quot;Limits of the proof, stated plainly&quot;">​</a></h2><p>Two honest caveats for the reader who wants to rely on this:</p><ol><li><strong>Convergence is best-effort.</strong> The lattice runs a bounded fixpoint (<code>value.rs:403</code>); when it terminates early on analyzing loops, narrowed ranges can be too narrow. The analysis records a <code>converged</code> flag when this happens - and, as of this revision, prunes based on ranges still consult it inconsistently. Treat a lattice-based &quot;proven clean&quot; on a deep loop as provisional until that flag is enforced (tracked as a roadmap correctness item).</li><li><strong>Branch sharpening covers what the predicate implies numerically.</strong><code>typeof x === &#39;string&#39;</code> or truthiness checks narrow the <em>type</em>, not attacker payload content; they do not clear taint on their own today.</li></ol><p>None of these caveats make the guard story weaker than the textual status quo it replaced - they are here so nobody takes &quot;proven&quot; broader than the engine actually guarantees.</p>',11)])])}const g=a(r,[["render",s]]);export{p as __pageData,g as default};
